 when r in('private.response_submit_commands','private.response_withdraw_commands','private.response_revision_resolution_commands',
  'public.marketplace_responses','public.worker_match_preferences','private.worker_calendar_events','public.opportunity_deliveries') then 't.worker_account_id=$1'
 when r in('public.profile_availability_rules','public.profile_availability_windows') then 't.profile_id in(select id from public.app_profiles where account_id=$1)'
 when r='private.worker_calendar_serialization' then 't.worker_profile_id in(select id from public.app_profiles where account_id=$1)'
 when r in('public.need_sensitive','public.need_geography','public.need_requirement_details','private.need_revision_events','private.need_publication_decisions',
  'private.dispatch_schedule','public.dispatch_rounds') then 't.need_id in(select id from public.needs where requester_account_id=$1)'
 when r='public.needs' then 't.requester_account_id=$1'
 when r in('private.response_application_snapshots','public.marketplace_response_versions') then 't.response_id in(select id from public.marketplace_responses where worker_account_id=$1)'
 when r='private.preselection_qa_questions' then 't.asker_account_id=$1'
 when r='private.preselection_qa_answer_versions' then 't.answered_by_account_id=$1'
 when r='private.preselection_qa_policy_decisions' then
  '(t.question_id in(select id from private.preselection_qa_questions where asker_account_id=$1) or t.need_id in(select id from public.needs where requester_account_id=$1) or t.id in(select policy_decision_id from private.qa_ai_commands where account_id=$1))'
 when r='private.preselection_qa_materiality_decisions' then
  '(t.question_id in(select id from private.preselection_qa_questions where asker_account_id=$1) or t.need_id in(select id from public.needs where requester_account_id=$1) or t.id in(select materiality_decision_id from private.qa_ai_commands where account_id=$1))'
 when r in('private.preselection_qa_commands','private.account_block_commands','private.agreement_location_commands','private.agreement_location_points') then 't.actor_account_id=$1'
 when r in('public.agreement_messages','private.group_messages_v5') then 't.sender_account_id=$1'
 when r='public.agreement_change_proposals' then 't.agreement_id in(select id from public.agreements where $1 in(requester_account_id,worker_account_id))'
 when r='public.agreement_versions' then 't.agreement_id in(select id from public.agreements where $1 in(requester_account_id,worker_account_id))'
 when r='public.agreement_execution' then 't.problem_opened_by=$1'
 when r='public.access_grants' then '$1 in(t.granted_by_account_id,t.granted_to_account_id)'
 when r in('public.notification_preferences','public.notification_push_devices') then 't.user_id=$1'
 when r='public.notification_push_attempts' then 't.delivery_id in(select id from public.notification_deliveries where recipient_user_id=$1) or t.device_id in(select id from public.notification_push_devices where user_id=$1)'
 when r='public.notification_deliveries' then 't.recipient_user_id=$1'
 when r='public.user_activity_events' then 't.recipient_user_id=$1 or t.entity_id in(select id from public.needs where requester_account_id=$1)'
 when r='private.marketplace_audit_log' then 't.actor_user_id=$1 or t.entity_id in(select id from public.needs where requester_account_id=$1) or t.entity_id in(select id from public.marketplace_responses where worker_account_id=$1)'
 else null end;
end $function$
$d12_restore_02$;
  -- private.closure_redaction_patch_v5(text,jsonb,uuid,uuid)
  execute replace($d12_restore_03$CREATE OR REPLACE FUNCTION private.closure_redaction_patch_v5(r text, t jsonb, a uuid, g uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb:='{}';k text;h text;ag public.agreements;terms jsonb;
begin
 if r is null or t is null or a is null or g is null or not(r=any(private.closure_redaction_relations_v5()))
 then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
 if r='public.agreement_invalidations_v1' then
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
 h:=encode(extensions.digest(convert_to('AF-D22:ERASED:'||r||':'||coalesce(t->>'id',t->>'client_request_id',t->>'conversation_id',t->>'review_id',t->>'account_id','subject'),'UTF8'),'sha256'),'hex');
 -- Support command receipts are metadata only. A related scoped case keeps its
 -- exact recovery/hash contract until that exception is resolved; no narrative
 -- is copied into the redaction ledger. Cancelled opaque tombstones stay usable.
 if r in('private.support_commands_v5','private.support_grant_commands_v5') then return null;end if;
 if r in('public.ai_conversations','public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.worker_ai_sessions','private.ai_task_reviews','private.worker_ai_reviews','private.need_draft_save_commands')
 and exists(select 1 from private.retention_holds where account_id=a and active and conversation_id=
  case when r='public.ai_conversations' then (t->>'id')::uuid else (t->>'conversation_id')::uuid end) then return null;end if;
 if r='private.ai_task_review_commands' and exists(select 1 from private.ai_task_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='private.worker_ai_saves' and exists(select 1 from private.worker_ai_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='public.ai_structured_facts' then
  if t->'superseded_by'<>'null'::jsonb then return jsonb_build_object('operation','UPDATE','patch',jsonb_build_object('superseded_by',null));end if;
  if exists(select 1 from public.ai_structured_facts where superseded_by=(t->>'id')::uuid) then return null;end if;
 end if;
 if r in('public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'public.need_sensitive','public.need_geography','public.need_requirement_details',
  'private.data_export_artifacts','public.notification_push_attempts','public.notification_deliveries',
  'public.notification_push_devices','public.notification_preferences','public.opportunity_deliveries',
  'private.dispatch_schedule','public.access_grants','public.profile_availability_rules','public.profile_availability_windows',
  'public.worker_match_preferences','private.worker_calendar_events','private.worker_calendar_serialization',
  'private.support_read_markers_v5','private.group_message_visibility_v5') then
  if r='private.data_export_artifacts' and exists(select 1 from storage.objects where bucket_id='data-export-artifacts' and name=t->>'object_path')
  then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='private.agreement_voice_uploads_v1' then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if exists(select 1 from storage.objects where bucket_id='agreement-voice' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r in('private.owned_media_assets','private.agreement_photo_uploads_v5') then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if private.closure_erasure_media_protected_v5(a,t->>'storage_path') then return null;end if;
  if exists(select 1 from storage.objects where bucket_id='profile-media' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='public.app_accounts' then p:=jsonb_build_object('email','','phone','','full_name','','city','');
 elsif r='public.app_profiles' then p:=jsonb_build_object('display_name','','city','','headline','','bio','','avatar_path',null,
  'portfolio','[]'::jsonb,'skills','[]'::jsonb,'tools','[]'::jsonb,'licenses','[]'::jsonb,'vehicles','[]'::jsonb,'exclusions','[]'::jsonb,
  'years_experience',0,'radius_km',1,'available_now',false,'available_now_expires_at',null,'team_capacity',1,
  'minimum_fee_rsd',0,'rating_requester',null,'rating_worker',null,'operating_country_code',null,'profile_status','CLOSED');
 elsif r='public.needs' then p:=jsonb_build_object('title','Obrisan zadatak','description','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.','category','OBRISANO',
  'approximate_city','','approximate_area','','approximate_lat',null,'approximate_lng',null,
  'starts_at',null,'ends_at',null,'required_skills','[]'::jsonb,'required_tools','[]'::jsonb,'required_vehicles','[]'::jsonb,'required_licenses','[]'::jsonb,
  'public_photo_paths','[]'::jsonb,'requester_price_rsd',null,'response_deadline',null,'urgent',false,
  'urgent_activated_at',null,'urgent_expires_at',null,'urgent_policy_version',null,'remaining_search_close_reason',null);
 elsif r in('private.ai_task_reviews','private.worker_ai_reviews') then p:=jsonb_build_object('envelope',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.worker_ai_sessions' then p:=jsonb_build_object('candidate',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.ai_task_review_commands' then
  foreach k in array array['evaluation_binding','evaluation','published'] loop
   if t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 elsif r='private.need_revision_events' then p:=jsonb_build_object('previous_material_snapshot',jsonb_build_object('erasedBy','AF-D22'),'new_material_snapshot',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='public.data_export_requests' then p:=jsonb_build_object('active_export_attempt_id',null,
  'export_revoked_at',coalesce(nullif(t->'export_revoked_at','null'::jsonb),to_jsonb((select requested_at from private.closure_executions_v5 where generation=g and account_id=a))));
 elsif r='private.need_publication_decisions' then p:=jsonb_build_object('public_geography_snapshot',jsonb_build_object('erasedBy','AF-D22'),'public_media_refs','[]'::jsonb,'reviewer_provenance','{}'::jsonb,'service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.preselection_qa_questions' then p:=jsonb_build_object('question_text','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.');
 elsif r='private.preselection_qa_answer_versions' then p:=jsonb_build_object('answer_text','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.');
 elsif r in('private.preselection_qa_policy_decisions','private.preselection_qa_materiality_decisions') then
  if exists(select 1 from private.qa_ai_commands q where q.account_id<>a and
   (case when r='private.preselection_qa_policy_decisions' then q.policy_decision_id else q.materiality_decision_id end)=(t->>'id')::uuid
   and not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
    where e.account_id=q.account_id and ac.kind='RELATIONAL_REDACT' and ac.state='VERIFIED')) then return null;end if;
  p:=jsonb_build_object('service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.response_application_snapshots' then p:=jsonb_build_object('worker_skills','[]'::jsonb,'worker_tools','[]'::jsonb,'worker_licenses','[]'::jsonb,'worker_vehicles','[]'::jsonb);
 elsif r in('public.marketplace_responses','public.marketplace_response_versions') then
  if exists(select 1 from public.agreements x where x.selected_response_id=coalesce(t->>'response_id',t->>'id')::uuid and private.closure_erasure_agreement_protected_v5(x.id)) then return null;end if;
  p:=jsonb_build_object('scope_note','');if t?'bounded_message' then p:=p||jsonb_build_object('bounded_message','');end if;
 elsif r='public.agreement_messages' then
  -- A selected Support copy survives in its immutable scoped snapshot. The
  -- original ordinary chat row does not need the same plaintext forever.
  p:=jsonb_build_object('body','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.','photo_asset_ids','[]'::jsonb,'voice_asset_id',null);
 elsif r='private.group_messages_v5' then p:=jsonb_build_object('body','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.');
 elsif r in('public.agreement_versions','public.agreement_change_proposals') then
  if private.closure_erasure_agreement_protected_v5((t->>'agreement_id')::uuid) then return null;end if;
  k:=case when r='public.agreement_versions' then 'terms' else 'proposed_terms' end;
  if exists(select 1 from private.closure_scope_sources_v5 where account_id=a and generation=g and agreement_id=(t->>'agreement_id')::uuid
   and source_kind=case when r='public.agreement_versions' then 'VERSION' else 'PROPOSAL' end
   and source_id=case when r='public.agreement_versions' then t->>'version' else t->>'id' end and scope_author=a) then
   terms:=(t->k)||jsonb_build_object('scope_note','');p:=jsonb_build_object(k,terms);
  end if;
  if r='public.agreement_change_proposals' and t->>'proposed_by_account_id'=a::text then p:=p||jsonb_build_object('reason','Sadr@@U017E@@aj uklonjen pri zatvaranju naloga.');end if;
  if p='{}'::jsonb then return null;end if;
 elsif r='public.agreement_execution' then
  -- The source problem itself is an unresolved evidence exception.
  if t->'problem_opened_at'<>'null'::jsonb then return null;end if;
  p:=jsonb_build_object('problem_narrative',null);
 elsif r='private.agreement_location_points' then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 elsif r='public.user_activity_events' then
  if t->>'recipient_user_id'=a::text then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
  p:=jsonb_build_object('payload',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.marketplace_audit_log' then p:=jsonb_build_object('detail',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.retention_holds' then
  if t->'active'='true'::jsonb then return null;end if;
  p:=jsonb_build_object('hold_key','AF-D22:'||(t->>'id'));
 elsif r='private.ai_test_accounts_v5' then
  if t->'retired_at'='null'::jsonb then p:=jsonb_build_object('retired_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 elsif r='private.support_operator_grants_v5' then
  if t->'active'='true'::jsonb then p:=jsonb_build_object('active',false,'revision',(t->>'revision')::integer+1,'updated_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 end if;
 -- Content-derived request hashes are no longer original-content proofs after
 -- erasure. Policy/document/source-program digests and charged units are kept.
 foreach k in array array['request_hash','input_hash','input_sha256','text_sha256','semantic_hash','content_fingerprint',
  'question_fingerprint','answer_fingerprint','context_hash','body_hash','body_sha256','completion_hash','source_hash','base_hash',
  'canonical_fingerprint','private_materiality_marker','content_hash','evaluation_result_hash','need_edit_base_fingerprint'] loop
  if t?k and jsonb_typeof(t->k)='string' then p:=p||jsonb_build_object(k,h);end if;
 end loop;
 -- These JSON command results are private source copies, not immutable legal
 -- terms. Keep identity/state columns for anti-replay, never old narrative JSON.
 if r in('private.requester_identity_commands','private.worker_ai_saves','private.need_draft_save_commands',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.qa_ai_commands',
  'private.need_edit_commands','private.need_publish_commands','private.response_submit_commands','private.response_withdraw_commands',
  'private.response_revision_resolution_commands','private.remaining_search_close_commands','private.preselection_qa_commands',
  'private.account_block_commands','private.retention_jobs','private.support_commands_v5','private.support_grant_commands_v5') then
  foreach k in array array['receipt','result'] loop
   if t?k and t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 end if;
 -- An operator's note about a person is not audit metadata the subject must live with. The
 -- lineage class, its revision and its timestamps stay; the free text becomes a fixed code.
 if r in('private.account_lineage_v5','private.account_lineage_events_v5') then
  p:=p||jsonb_build_object('reason','CLOSURE_ERASED_OPERATOR_NOTE','source_ref','CLOSURE_ERASED_SOURCE_REF');
 end if;
 if p='{}'::jsonb or t@>p then return null;end if;
 return jsonb_build_object('operation','UPDATE','patch',p);
end $function$
$d12_restore_03$,'@@U017E@@',chr(382));
  -- private.data_export_dataset_catalog()
  execute $d12_restore_04$CREATE OR REPLACE FUNCTION private.data_export_dataset_catalog()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ select '[{"key": "account", "fields": ["activeMode", "city", "createdAt", "email", "fullName", "id", "phone"], "dataClass": "ACCOUNT_IDENTITY", "ownershipFilter": "t.id=REQUEST_ACCOUNT"}, {"key": "profiles", "fields": ["bio", "city", "displayName", "headline", "id", "kind", "operatingCountryCode", "skills", "status"], "dataClass": "PROFILE_DATA", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "availabilityWindows", "fields": ["endsAt", "id", "label", "profileId", "startsAt", "state"], "dataClass": "PROFILE_DATA", "ownershipFilter": "p.account_id=REQUEST_ACCOUNT"}, {"key": "availabilityRules", "fields": ["active", "endTime", "endsOn", "id", "label", "profileId", "startTime", "startsOn", "weekdays"], "dataClass": "PROFILE_DATA", "ownershipFilter": "p.account_id=REQUEST_ACCOUNT"}, {"key": "calendar", "fields": ["agreementId", "endsAt", "startsAt", "state"], "dataClass": "PROFILE_DATA", "ownershipFilter": "t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "needs", "fields": ["countryCode", "description", "endsAt", "executionMode", "id", "requiredSlots", "revision", "startsAt", "status", "timezone", "title"], "dataClass": "NEED_PUBLIC", "ownershipFilter": "t.requester_account_id=REQUEST_ACCOUNT"}, {"key": "needPrivate", "fields": ["accessNotes", "exactAddress", "latitude", "longitude", "needId", "resolvedPoints"], "dataClass": "NEED_SENSITIVE", "ownershipFilter": "n.requester_account_id=REQUEST_ACCOUNT"}, {"key": "responses", "fields": ["coveredSlots", "createdAt", "id", "kind", "message", "needId", "needRevision", "priceRsd", "scopeNote", "status"], "dataClass": "RESPONSES_SELECTION", "ownershipFilter": "t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownQuestions", "fields": ["createdAt", "id", "needId", "question", "status"], "dataClass": "PRESELECTION_QA", "ownershipFilter": "t.asker_account_id=REQUEST_ACCOUNT"}, {"key": "ownAnswers", "fields": ["answer", "createdAt", "id", "questionId", "version"], "dataClass": "PRESELECTION_QA", "ownershipFilter": "t.answered_by_account_id=REQUEST_ACCOUNT"}, {"key": "agreements", "fields": ["createdAt", "currentVersion", "id", "needId", "status"], "dataClass": "AGREEMENT_CORE", "ownershipFilter": "t.requester_account_id=REQUEST_ACCOUNT or t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementMessages", "fields": ["agreementId", "body", "createdAt", "id", "agreementVersion", "assetIds", "voiceAssetId"], "dataClass": "AGREEMENT_MESSAGES", "ownershipFilter": "t.sender_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"}, {"key": "consent", "fields": ["acceptedAt", "id", "privacySha256", "privacyVersion", "termsSha256", "termsVersion"], "dataClass": "LEGAL_CONSENT", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "notifications", "fields": ["body", "channel", "createdAt", "id", "readAt", "role", "state", "title"], "dataClass": "NOTIFICATION_DELIVERY", "ownershipFilter": "t.recipient_user_id=REQUEST_ACCOUNT"}, {"key": "aiMessages", "fields": ["content", "conversationId", "createdAt", "id", "role"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "mediaMetadata", "fields": ["bytesIncluded", "createdAt", "name"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.bucket_id=''profile-media'' and split_part(t.name,''/'',1)=REQUEST_ACCOUNT::text"}, {"key": "exportRequests", "fields": ["completedAt", "id", "kind", "requestedAt", "status"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAudit", "fields": ["createdAt", "entityId", "entityType", "eventType", "id"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.actor_user_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementReviews", "fields": ["agreementId", "createdAt", "id", "rating", "tags"], "dataClass": "AGREEMENT_REVIEWS", "ownershipFilter": "t.reviewer_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"}, {"key": "ownSafetyReports", "fields": ["agreementId", "category", "createdAt", "id", "narrative", "needId", "reason", "status"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.reporter_account_id=REQUEST_ACCOUNT"}, {"key": "ownBlocks", "fields": ["active", "revision", "targetAccountId", "updatedAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.blocker_account_id=REQUEST_ACCOUNT"}, {"key": "workerAiDrafts", "fields": ["conversationId", "createdAt", "profile", "profileId", "revision", "safety"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiReviews", "fields": ["activate", "conversationId", "createdAt", "id", "profile", "revision"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiReviews", "fields": ["conversationId", "createdAt", "draftId", "draftRevision", "id", "privateFacts", "publicFacts", "responseDeadline"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiFacts", "fields": ["conversationId", "facts", "id"], "dataClass": "AI_VOLATILE", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiTurns", "fields": ["cancelledAt", "conversationId", "createdAt", "id", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiSaves", "fields": ["createdAt", "reviewId"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "taskReviewCommands", "fields": ["createdAt", "needId", "needRevision", "reviewId", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiTurns", "fields": ["cancelledAt", "conversationId", "createdAt", "id", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "qaClassifications", "fields": ["createdAt", "id", "materiality", "needId", "needRevision", "outcome", "questionId", "state", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "qaCommands", "fields": ["createdAt", "questionId", "status", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT"}, {"key": "ownedMediaAssets", "fields": ["byteSize", "bytesIncluded", "conversationId", "createdAt", "height", "id", "profileId", "scope", "selected", "state", "width"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAdmission", "fields": ["admittedAt", "retiredAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAllocations", "fields": ["allocatedMaximumMicrousd", "createdAt", "kind", "measuredProviderCharge", "settledAt", "settledMicrousd", "settlementBasis"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureRequests", "fields": ["closedAt", "id", "preparedAt", "requestedAt", "revision", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureExecution", "fields": ["closedAt", "requestId", "requestedAt", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureActions", "fields": ["dispatchedAt", "evidence", "kind", "state", "verifiedAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMessages", "fields": ["id", "groupId", "body", "createdAt"], "dataClass": "AGREEMENT_MESSAGES", "ownershipFilter": "t.sender_account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMemberships", "fields": ["groupId", "agreementId", "joinedAt", "endedAt"], "dataClass": "AGREEMENT_CORE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationSnapshots", "fields": ["agreementId", "agreementVersion", "latitude", "longitude", "accuracyMeters", "capturedAt", "sharedAt"], "dataClass": "NEED_SENSITIVE", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and a.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationCommands", "fields": ["agreementId", "agreementVersion", "kind", "state", "createdAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and REQUEST_ACCOUNT in(a.requester_account_id,a.worker_account_id)"}, {"key": "ownAcceptedTaskMedia", "fields": ["agreementId", "agreementVersion", "needId", "needRevision", "state", "assets", "capturedAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and a.requester_account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportCases", "fields": ["id", "caseNumber", "channel", "topic", "title", "desiredOutcome", "context", "status", "revision", "createdAt", "updatedAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvents", "fields": ["id", "caseId", "sequence", "kind", "authorRole", "body", "decisionId", "appealId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportDecisions", "fields": ["id", "caseId", "caseRevision", "outcome", "reasonCode", "explanation", "effect", "evidenceIds", "priorDecisionId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportAppeals", "fields": ["id", "caseId", "decisionId", "status", "decisionResultId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvidence", "fields": ["id", "caseId", "eventId", "reference", "createdAt", "bytesIncluded"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.submitted_by_account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportCommands", "fields": ["kind", "state", "caseId", "createdAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportReadMarkers", "fields": ["caseId", "sequence", "updatedAt"], "dataClass": "NOTIFICATION_DELIVERY", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementPhotos", "fields": ["id", "agreementId", "agreementVersion", "messageId", "state", "width", "height", "byteSize", "createdAt", "cancelledAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownErasureSteps", "fields": ["generation", "ordinal", "state", "rowsChanged", "verifiedAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementVoice", "fields": ["id", "agreementId", "agreementVersion", "messageId", "state", "durationMs", "byteSize", "createdAt", "cancelledAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}]'::jsonb $function$
$d12_restore_04$;
  -- private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)
  execute $d12_restore_05$CREATE OR REPLACE FUNCTION private.data_export_snapshot(p_account_id uuid, p_receipt_id uuid, p_binding jsonb, p_cutoff timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 with configured as (select value as config from jsonb_array_elements(p_binding#>'{delivery,datasets}')),
 owned_rows as materialized (select 'account' as key,jsonb_build_object('id',t.id,'email',t.email,'fullName',t.full_name,'city',t.city,'phone',t.phone,'activeMode',t.active_mode,'createdAt',t.created_at) as value from public.app_accounts t where t.id=p_account_id
union all
select 'profiles' as key,jsonb_build_object('id',t.id,'kind',t.kind,'displayName',t.display_name,'city',t.city,'headline',t.headline,'bio',t.bio,'status',t.profile_status,'skills',t.skills,'operatingCountryCode',t.operating_country_code) as value from public.app_profiles t where t.account_id=p_account_id
union all
select 'availabilityWindows' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.availability_state,'label',t.label) as value from public.profile_availability_windows t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'availabilityRules' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'weekdays',t.weekdays,'startTime',t.start_time,'endTime',t.end_time,'startsOn',t.starts_on,'endsOn',t.ends_on,'active',t.active,'label',t.label) as value from public.profile_availability_rules t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'calendar' as key,jsonb_build_object('agreementId',t.agreement_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.state) as value from private.worker_calendar_events t where t.worker_account_id=p_account_id
union all
select 'needs' as key,jsonb_build_object('id',t.id,'title',t.title,'description',t.description,'status',t.status,'revision',t.revision,'countryCode',t.task_country_code,'timezone',t.task_timezone,'executionMode',t.execution_location_mode,'startsAt',t.starts_at,'endsAt',t.ends_at,'requiredSlots',t.required_slots) as value from public.needs t where t.requester_account_id=p_account_id
union all
select 'needPrivate' as key,jsonb_build_object('needId',t.need_id,'exactAddress',t.exact_address,'accessNotes',t.access_notes,'latitude',t.exact_lat,'longitude',t.exact_lng,'resolvedPoints',coalesce((select jsonb_agg(jsonb_build_object('slot',v->'slot','latitudeE6',v->'latitudeE6','longitudeE6',v->'longitudeE6','address',v->'address','accessNotes',v->'accessNotes') order by v->>'slot') from jsonb_array_elements(t.resolved_location#>'{value,points}') v),'[]'::jsonb)) as value from public.need_sensitive t join public.needs n on n.id=t.need_id where n.requester_account_id=p_account_id
union all
select 'responses' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'kind',t.response_kind,'status',t.status,'needRevision',t.submitted_against_need_revision,'priceRsd',t.price_rsd,'coveredSlots',t.covered_slots,'scopeNote',t.scope_note,'message',t.bounded_message,'createdAt',t.created_at) as value from public.marketplace_responses t where t.worker_account_id=p_account_id
union all
select 'ownQuestions' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'question',t.question_text,'status',t.status,'createdAt',t.created_at) as value from private.preselection_qa_questions t where t.asker_account_id=p_account_id
union all
select 'ownAnswers' as key,jsonb_build_object('id',t.id,'questionId',t.question_id,'version',t.answer_version,'answer',t.answer_text,'createdAt',t.created_at) as value from private.preselection_qa_answer_versions t where t.answered_by_account_id=p_account_id
union all
select 'agreements' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'status',t.status,'currentVersion',t.current_version,'createdAt',t.created_at) as value from public.agreements t where t.requester_account_id=p_account_id or t.worker_account_id=p_account_id
union all
select 'ownAgreementMessages' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'body',t.body,'createdAt',t.created_at,'agreementVersion',t.agreement_version,'assetIds',to_jsonb(t.photo_asset_ids),'voiceAssetId',t.voice_asset_id) as value from public.agreement_messages t join public.agreements a on a.id=t.agreement_id where t.sender_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'consent' as key,jsonb_build_object('id',t.id,'termsVersion',t.terms_version_label,'termsSha256',t.terms_content_sha256,'privacyVersion',t.privacy_version_label,'privacySha256',t.privacy_content_sha256,'acceptedAt',t.accepted_at) as value from public.account_legal_acceptance_events t where t.account_id=p_account_id
union all
select 'notifications' as key,jsonb_build_object('id',t.id,'role',t.recipient_role,'channel',t.channel,'state',t.state,'title',t.title,'body',t.body,'createdAt',t.created_at,'readAt',t.read_at) as value from public.notification_deliveries t where t.recipient_user_id=p_account_id
union all
select 'aiMessages' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'role',t.role,'content',t.body,'createdAt',t.created_at) as value from public.ai_messages t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'mediaMetadata' as key,jsonb_build_object('name',t.name,'createdAt',t.created_at,'bytesIncluded',false) as value from storage.objects t where t.bucket_id='profile-media' and split_part(t.name,'/',1)=p_account_id::text
union all
select 'exportRequests' as key,jsonb_build_object('id',t.id,'kind',t.request_kind,'status',t.status,'requestedAt',t.requested_at,'completedAt',t.completed_at) as value from public.data_export_requests t where t.account_id=p_account_id
union all
select 'ownAudit' as key,jsonb_build_object('id',t.id,'eventType',t.event_type,'entityType',t.entity_type,'entityId',t.entity_id,'createdAt',t.created_at) as value from private.marketplace_audit_log t where t.actor_user_id=p_account_id
union all
select 'ownAgreementReviews' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'rating',t.rating,'tags',t.tags,'createdAt',t.created_at) as value from private.agreement_reviews t join public.agreements a on a.id=t.agreement_id where t.reviewer_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'ownSafetyReports' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'agreementId',t.agreement_id,'category',t.category,'reason',t.reason,'narrative',t.narrative,'status',t.status,'createdAt',t.created_at) as value from private.safety_reports t where t.reporter_account_id=p_account_id
union all
select 'ownBlocks' as key,jsonb_build_object('targetAccountId',t.blocked_account_id,'active',t.active,'revision',t.revision,'updatedAt',t.updated_at) as value from private.account_blocks t where t.blocker_account_id=p_account_id
union all
select 'workerAiDrafts' as key,jsonb_build_object('conversationId',t.conversation_id,'profileId',t.profile_id,'revision',t.revision,'safety',t.safety,'profile',private.data_export_worker_candidate_v5(t.candidate),'createdAt',t.created_at) as value from private.worker_ai_sessions t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'workerAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'revision',t.revision,'activate',private.data_export_scalar_v5(t.envelope->'activate','boolean'),'profile',private.data_export_worker_candidate_v5(t.envelope->'profile'),'createdAt',t.created_at) as value from private.worker_ai_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'draftId',private.data_export_scalar_v5(t.envelope->'draftId','string'),'draftRevision',private.data_export_scalar_v5(t.envelope->'draftRevision','number'),'responseDeadline',private.data_export_scalar_v5(t.envelope->'responseDeadline','string'),'publicFacts',private.data_export_task_facts_v5(t.envelope->'publicProjection'),'privateFacts',private.data_export_task_facts_v5(t.envelope->'ownerPrivateProjection'),'createdAt',t.created_at) as value from private.ai_task_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiFacts' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'facts',private.data_export_task_facts_v5(jsonb_build_array(jsonb_build_object('key',t.fact_key,'value',t.fact_value,'displayValue',t.display_value,'status',t.status)))) as value from public.ai_structured_facts t join public.ai_conversations c on c.id=t.conversation_id where c.account_id=p_account_id
union all
select 'workerAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'createdAt',t.created_at,'cancelledAt',t.cancelled_at) as value from private.worker_ai_turns t where t.account_id=p_account_id
union all
select 'workerAiSaves' as key,jsonb_build_object('reviewId',t.review_id,'createdAt',t.created_at) as value from private.worker_ai_saves t where t.account_id=p_account_id
union all
select 'taskReviewCommands' as key,jsonb_build_object('reviewId',t.review_id,'needId',t.need_id,'needRevision',t.need_revision,'state',t.state,'createdAt',t.created_at) as value from private.ai_task_review_commands t where t.account_id=p_account_id
union all
select 'taskAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'cancelledAt',t.cancelled_at,'createdAt',t.created_at) as value from private.ai_need_turn_commands t where t.account_id=p_account_id
union all
select 'qaClassifications' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'needRevision',t.need_revision,'questionId',t.question_id,'type',t.command_type,'state',t.state,'outcome',t.outcome,'materiality',t.materiality,'createdAt',t.created_at) as value from private.qa_ai_commands t where t.account_id=p_account_id
union all
select 'qaCommands' as key,jsonb_build_object('type',t.command_type,'questionId',private.data_export_scalar_v5(t.result->'questionId','string'),'status',private.data_export_scalar_v5(t.result->'status','string'),'createdAt',t.created_at) as value from private.preselection_qa_commands t where t.actor_account_id=p_account_id
union all
select 'ownedMediaAssets' as key,jsonb_build_object('id',t.id,'scope',t.scope,'conversationId',t.conversation_id,'profileId',t.profile_id,'state',t.state,'selected',t.selected,'width',t.width,'height',t.height,'byteSize',t.byte_size,'bytesIncluded',false,'createdAt',t.created_at) as value from private.owned_media_assets t where t.account_id=p_account_id
union all
select 'testAdmission' as key,jsonb_build_object('admittedAt',t.admitted_at,'retiredAt',t.retired_at) as value from private.ai_test_accounts_v5 t where t.account_id=p_account_id
union all
select 'testAllocations' as key,jsonb_build_object('kind',t.kind,'allocatedMaximumMicrousd',t.max_cost_microusd,'measuredProviderCharge',coalesce(t.settlement_basis='MEASURED',false),'settledMicrousd',t.settled_microusd,'settlementBasis',t.settlement_basis,'settledAt',t.settled_at,'createdAt',t.created_at) as value from private.ai_test_reservations_v5 t where t.account_id=p_account_id
union all
select 'closureRequests' as key,jsonb_build_object('id',t.id,'state',t.state,'revision',t.revision,'requestedAt',t.requested_at,'preparedAt',t.prepared_at,'closedAt',t.closed_at) as value from private.account_closure_requests t where t.account_id=p_account_id
union all
select 'closureExecution' as key,jsonb_build_object('requestId',t.request_id,'state',t.state,'requestedAt',t.requested_at,'closedAt',t.closed_at) as value from private.closure_executions_v5 t where t.account_id=p_account_id
union all
select 'closureActions' as key,jsonb_build_object('kind',t.kind,'state',t.state,'dispatchedAt',t.dispatched_at,'verifiedAt',t.verified_at,'evidence',t.evidence) as value from private.closure_actions_v5 t where t.account_id=p_account_id
union all
select 'ownGroupMessages' as key,jsonb_build_object('id',t.id,'groupId',t.group_id,'body',t.body,'createdAt',t.created_at) as value
 from private.group_messages_v5 t where t.sender_account_id=p_account_id
union all
select 'ownGroupMemberships' as key,jsonb_build_object('groupId',t.group_id,'agreementId',t.agreement_id,'joinedAt',t.joined_at,'endedAt',t.ended_at) as value
 from private.group_memberships_v5 t where t.account_id=p_account_id
union all
select 'ownLocationSnapshots' as key,jsonb_build_object('agreementId',c.agreement_id,'agreementVersion',c.agreement_version,
 'latitude',t.latitude,'longitude',t.longitude,'accuracyMeters',t.accuracy_meters,'capturedAt',t.captured_at,'sharedAt',t.shared_at) as value
 from private.agreement_location_points t join private.agreement_location_commands c using(actor_account_id,client_request_id)
 join public.agreements a on a.id=c.agreement_id where t.actor_account_id=p_account_id and a.worker_account_id=p_account_id and c.kind='SHARE' and c.state='COMMITTED'
union all
select 'ownLocationCommands' as key,jsonb_build_object('agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'kind',t.kind,'state',t.state,'createdAt',t.created_at) as value
 from private.agreement_location_commands t join public.agreements a on a.id=t.agreement_id where t.actor_account_id=p_account_id and p_account_id in(a.requester_account_id,a.worker_account_id)
union all
select 'ownAcceptedTaskMedia' as key,jsonb_build_object('agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'needId',t.need_id,'needRevision',t.need_revision,'state',t.state,'capturedAt',t.captured_at,'bytesIncluded',false,
 'assets',(select coalesce(jsonb_agg(jsonb_build_object('assetId',x->>'assetId','width',private.data_export_scalar_v5(x->'width','number'),'height',private.data_export_scalar_v5(x->'height','number'),'byteSize',private.data_export_scalar_v5(x->'byteSize','number')) order by ordinal),'[]') from jsonb_array_elements(t.assets) with ordinality as j(x,ordinal))) as value
 from private.agreement_media_snapshots_v5 t join public.agreements a on a.id=t.agreement_id where t.account_id=p_account_id and a.requester_account_id=p_account_id
union all
select 'ownSupportCases',jsonb_build_object('id',t.id,'caseNumber',t.case_number::text,'channel',t.channel,'topic',t.topic,'title',t.title,'desiredOutcome',t.desired_outcome,'context',t.context,'status',t.status,'revision',t.revision,'createdAt',t.created_at,'updatedAt',t.updated_at) from private.support_cases_v5 t where t.account_id=p_account_id
union all
select 'ownSupportEvents',jsonb_build_object('id',t.id,'caseId',t.case_id,'sequence',t.sequence::text,'kind',t.kind,'authorRole',t.author_role,'body',case when t.kind='SAFETY_REPORT' then (select narrative from private.safety_reports where id=c.safety_report_id) else t.body end,'decisionId',t.decision_id,'appealId',t.appeal_id,'createdAt',t.created_at) from private.support_events_v5 t join private.support_cases_v5 c on c.id=t.case_id where c.account_id=p_account_id
union all
select 'ownSupportDecisions',jsonb_build_object('id',t.id,'caseId',t.case_id,'caseRevision',t.case_revision,'outcome',t.outcome,'reasonCode',t.reason_code,'explanation',t.explanation,'effect',t.effect,'evidenceIds',to_jsonb(t.evidence_ids),'priorDecisionId',t.prior_decision_id,'createdAt',t.created_at) from private.support_decisions_v5 t join private.support_cases_v5 c on c.id=t.case_id where c.account_id=p_account_id
union all
select 'ownSupportAppeals',jsonb_build_object('id',t.id,'caseId',t.case_id,'decisionId',t.decision_id,'status',t.status,'decisionResultId',t.decision_result_id,'createdAt',t.created_at) from private.support_appeals_v5 t join private.support_cases_v5 c on c.id=t.case_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'ownSupportEvidence',jsonb_build_object('id',t.id,'caseId',t.case_id,'eventId',t.event_id,'reference',t.snapshot,'createdAt',t.created_at,'bytesIncluded',false) from private.support_evidence_v5 t join private.support_cases_v5 c on c.id=t.case_id where t.submitted_by_account_id=p_account_id and c.account_id=p_account_id
union all
select 'ownSupportCommands',jsonb_build_object('kind',t.kind,'state',t.state,'caseId',t.case_id,'createdAt',t.created_at) from private.support_commands_v5 t where t.account_id=p_account_id
union all
select 'ownSupportReadMarkers',jsonb_build_object('caseId',t.case_id,'sequence',t.sequence::text,'updatedAt',t.updated_at) from private.support_read_markers_v5 t where t.account_id=p_account_id
union all
select 'ownAgreementPhotos',jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'messageId',t.attached_message_id,'state',t.state,
 'width',t.width,'height',t.height,'byteSize',t.byte_size,'createdAt',t.created_at,'cancelledAt',t.cancelled_at,'bytesIncluded',false) from private.agreement_photo_uploads_v5 t where t.account_id=p_account_id
union all
select 'ownAgreementVoice',jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'messageId',t.attached_message_id,'state',t.state,
 'durationMs',t.duration_ms,'byteSize',t.byte_size,'createdAt',t.created_at,'cancelledAt',t.cancelled_at,'bytesIncluded',false) from private.agreement_voice_uploads_v1 t where t.account_id=p_account_id
union all
select 'ownErasureSteps',jsonb_build_object('generation',t.generation,'ordinal',t.ordinal,'state',t.state,'rowsChanged',t.affected_rows,'verifiedAt',t.verified_at) from private.closure_redaction_steps_v5 t where t.account_id=p_account_id),
 projected as (select r.key,(select jsonb_object_agg(field,r.value->field order by field) from jsonb_array_elements_text(c.config->'fields') field) as value
 from owned_rows r join configured c on c.config->>'key'=r.key and c.config->>'mode'='INCLUDE'),
 grouped as (select c.config->>'key' as key,coalesce(jsonb_agg(p.value order by p.value::text) filter(where p.key is not null),'[]'::jsonb) as rows
 from configured c left join projected p on p.key=c.config->>'key' where c.config->>'mode'='INCLUDE' group by c.config->>'key')
 select jsonb_build_object('schemaVersion','USKOCI_DATA_EXPORT_V2','receiptId',p_receipt_id,'accountId',p_account_id,'snapshotAt',p_cutoff,
 'projectionVersion','OWN_ACCOUNT_V5_9','policy',jsonb_build_object('policyId',p_binding->'policyId','policyVersion',p_binding->'policyVersion','privacyDocumentId',p_binding->'privacyDocumentId','privacyContentSha256',p_binding->'privacyContentSha256','sha256',p_binding->'sha256'),
 'datasets',(select jsonb_object_agg(key,rows order by key) from grouped),
 'datasetCounts',(select jsonb_object_agg(key,jsonb_array_length(rows) order by key) from grouped),
 'reviewedOmissions',(select coalesce(jsonb_agg(config order by config->>'key'),'[]'::jsonb) from configured where config->>'mode'='EXCLUDE'))::text
 where exists(select 1 from public.app_accounts where id=p_account_id);
$function$
$d12_restore_05$;
  -- private.data_export_policy_binding()
  execute $d12_restore_06$CREATE OR REPLACE FUNCTION private.data_export_policy_binding()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets; m jsonb; d jsonb; c jsonb; seen text[]:='{}'; f jsonb; fields text[]; refs jsonb; privacy private.legal_document_versions; v_now timestamptz:=clock_timestamp();
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=v_now;
 if not found then return null; end if;
 m:=p.export_delivery;
 if jsonb_typeof(m) is distinct from 'object' or m-ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets'])
 or m->>'schemaVersion' is distinct from 'USKOCI_EXPORT_DELIVERY_V2' or m->>'projectionVersion' is distinct from 'OWN_ACCOUNT_V5_9'
 or jsonb_typeof(m->'projectionSha256') is distinct from 'string' or coalesce(m->>'projectionSha256','')!~'^[a-f0-9]{64}$'
 or m->>'projectionSha256' is distinct from private.data_export_projection_sha_v5()
 or m->>'cleanupMode' is distinct from 'DELETE_EXPORT_COPY' or m->>'snapshotCleanupMode' is distinct from 'DELETE_TEMP_SNAPSHOT'
 or coalesce(m->>'privacyDocumentId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[0-9a-f]{64}$' or coalesce(m->>'contentSha256','')!~'^[0-9a-f]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null; end if;
 foreach fields slice 1 in array ARRAY[ARRAY['artifactLifetimeSeconds','2592000'],ARRAY['snapshotLifetimeSeconds','2592000'],ARRAY['downloadLifetimeSeconds','900']] loop
   if jsonb_typeof(m->fields[1]) is distinct from 'number' or (m->>fields[1])!~'^[1-9][0-9]*$' or (m->>fields[1])::numeric>(fields[2])::numeric then return null; end if;
 end loop;
 if (m->>'downloadLifetimeSeconds')::integer>(m->>'artifactLifetimeSeconds')::integer then return null; end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active and retired_at is null and effective_at<=v_now and content_sha256=m->>'privacyContentSha256';
 if not found then return null; end if;
 if exists(select 1 from private.retention_data_classes dc where dc.active and dc.required and (not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=dc.code) or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'dataClass'=dc.code))) then return null; end if;
 if jsonb_typeof(m->'datasets') is distinct from 'array' or jsonb_array_length(m->'datasets')<>52 then return null; end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
   if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'key') is distinct from 'string' or d->>'key'=any(seen) then return null; end if;
   select value into c from jsonb_array_elements(private.data_export_dataset_catalog()) where value->>'key'=d->>'key';
   if not found then return null; end if;seen:=array_append(seen,d->>'key');
   if d->>'mode'='EXCLUDE' then
     if d-ARRAY['key','mode','reasonCode']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','reasonCode']) or jsonb_typeof(d->'reasonCode') is distinct from 'string' or d->>'reasonCode'!~'^[A-Z][A-Z0-9_]{0,63}$' or d->>'key'='account' then return null; end if;
   elsif d->>'mode'='INCLUDE' then
     if d-ARRAY['key','mode','fields']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','fields']) or jsonb_typeof(d->'fields') is distinct from 'array' then return null; end if;
     if jsonb_array_length(d->'fields')<1 or jsonb_array_length(d->'fields')>64 then return null; end if;fields:='{}';
     for f in select value from jsonb_array_elements(d->'fields') loop
       if jsonb_typeof(f)<>'string' or not((c->'fields') ? (f#>>'{}')) or f#>>'{}'=any(fields) then return null; end if; fields:=array_append(fields,f#>>'{}');
     end loop;
     if d->>'key'='account' and not('id'=any(fields)) then return null; end if;
     if d->>'key' in('mediaMetadata','ownedMediaAssets','ownAgreementPhotos','ownAgreementVoice','ownSupportEvidence') and not('bytesIncluded'=any(fields)) then return null; end if;
   else return null; end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(r) order by data_class),'[]'::jsonb) into refs from private.retention_policy_rules r where policy_id=p.id;
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'privacyDocumentId',privacy.id,'privacyContentSha256',privacy.content_sha256,'delivery',m,
 'sha256',encode(extensions.digest(convert_to(jsonb_build_object('policy',to_jsonb(p),'rules',refs,'privacy',to_jsonb(privacy),'catalog',private.data_export_dataset_catalog())::text,'UTF8'),'sha256'),'hex'));
exception when data_exception then return null;
end $function$
