    ('public.rpc_redact_account_closure_step_service(uuid,uuid,uuid,uuid)','0fd89c6c870f3496d485f97d8016ba7c'),
    ('private.closure_erasure_refresh_steps_v5(private.closure_executions_v5)','f228322985e8ae90bce17880d1ffd9c4'),
    ('private.support_reference_v5(uuid,jsonb)','94ad410f355654cffccd9de1084571bb'),
    ('public.rpc_support_find_context_v5(uuid,text,uuid)','66b392dcf118e3109e3a12ebd909c159'),
    ('private.audit_marketplace(uuid,text,text,uuid,integer,jsonb)','ef33e1d34afb1507071c47253a13c9b2'),
    ('private.emit_event(uuid,text,text,text,uuid,integer,text,text,text,text,jsonb,timestamptz)','67413effbbb3fa227397d355e0d4edfb'),
    ('private.safety_pair_blocked(uuid,uuid)','698fb21abb0379743bc7ab09d9f946ad'),
    ('private.accounts_same_world(uuid,uuid)','16f541f952d4e1e2dbb4fc87e594d572'),
    ('private.account_visibility_world(uuid)','876cfc16f0ed1c4d32b128e8e18bdcda'),
    ('private.ru4b_public_floor_reason(text)','3462ec034f1f9df9760e4729aa0d2c18'),
    ('private.data_export_projection_sha_v5()','f628ae258c3bae4a1d0fed0cde3dac53'),
    ('private.data_export_scalar_v5(jsonb,text)','e02fe0db0a56b90b74a29c2b81a38357'),
    ('private.data_export_array_v5(jsonb,text)','00933c589c16905b09318c080a2150f6'),
    ('private.data_export_worker_candidate_v5(jsonb)','aa9c5f1b7ab4711cda7cb16905de55a4'),
    ('private.data_export_task_facts_v5(jsonb)','b1552206df3434002e6d294befbca5b6'),
    ('public.rpc_submit_safety_report(uuid,uuid,uuid,text,text,text,uuid)','9249705c01cc3d29d178f1ebd331daeb')
  ) p(signature,body_md5) loop
    if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5 then
      raise exception 'D12_REVERT_BODY_NOT_RESTORED: %',pin.signature using errcode='55000';end if;
  end loop;
  if not exists(select 1 from pg_proc where oid='private.retention_ai_source_ready()'::regprocedure
      and (length(prosrc)-length(replace(prosrc,target_source,'')))=length(target_source)
      and md5(replace(replace(prosrc,E'\r\n',E'\n'),target_source,'__CERTIFIED_SOURCE__'))='bc85a1a744869abb6441e647b18b2195') then
    raise exception 'D12_REVERT_READINESS_NOT_RESTORED' using errcode='55000';end if;
  if private.data_export_projection_sha_v5() is distinct from '70009062e365b92295eba138a63868e84fd712ee270d9e6ea24237507e5eecfa' then
    raise exception 'D12_REVERT_PROJECTION_SHA_NOT_RESTORED' using errcode='55000';end if;

  -- Delta accounting 2/3: every table, column, constraint, trigger, policy, index and bucket is what it was before the application.
  execute surface_query into after_surface;
  if after_surface is distinct from before_surface then
    select string_agg(k||': +'||(select count(*) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' -'||(select count(*) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' added '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-')
      ||' removed '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-'),' | ')
      into diff_keys from jsonb_object_keys(before_surface) k where before_surface->k is distinct from after_surface->k;
    raise exception 'D12_REVERT_UNRELATED_CATALOG_DELTA: %',diff_keys using errcode='55000';
  end if;
  if (select string_agg(defaclnamespace::regnamespace::text||':'||defaclobjtype::text||':'||defaclacl::text,' | ' order by defaclnamespace::regnamespace::text,defaclobjtype::text) from pg_default_acl) is distinct from before_default_acls then
    raise exception 'D12_REVERT_DEFAULT_ACL_DELTA' using errcode='55000';end if;
  if to_regclass('private.agreement_review_comments_v1') is not null
     or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in(('private','guard_review_comment_mutation'),('private','review_comment_input_v1'),('public','rpc_submit_agreement_review_v2'),('public','rpc_get_my_agreement_review_v2'),('public','rpc_list_review_comments_v1'),('public','rpc_moderate_review_comment_service_v1')))
     or exists(select 1 from pg_trigger where tgname in('agreement_review_comment_closure_guard_v1','agreement_review_comment_mutation_guard_v1'))
     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in('agreement_review_comments_v1_author_idx','agreement_review_comments_v1_pkey','agreement_review_comments_v1_target_idx'))
     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','rls_private') and c.relname like 'agreement\_review\_comment%') then
    raise exception 'D12_REVERT_NEW_OBJECT_REMAINS' using errcode='55000';end if;

  -- Delta accounting 3/3: the retention catalog is what it was, the star table is untouched, the certificate is bound in its three places to the restored digest, nothing else moved.
  if (select jsonb_agg(to_jsonb(c) order by data_class) from private.closure_dataset_catalog_v5 c) is distinct from expected_datasets then
    raise exception 'D12_REVERT_CATALOG_DELTA' using errcode='55000';end if;
  if (select jsonb_agg(to_jsonb(c) order by c.code) from private.retention_data_classes c) is distinct from expected_classes
     or (select count(*) from private.retention_data_classes where required and active)<>15 then
    raise exception 'D12_REVERT_RETENTION_CLASSES_DELTA' using errcode='55000';end if;
  select md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by r.id),'')) into star_after from private.agreement_reviews r;
  if star_after is distinct from star_before then raise exception 'D12_REVERT_STAR_DATA_DELTA' using errcode='55000';end if;
  if cardinality(private.closure_redaction_relations_v5())<>75
     or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews')
        is distinct from '["agreementId","createdAt","id","rating","tags"]'::jsonb then
    raise exception 'D12_REVERT_CLOSURE_OR_EXPORT_NOT_RESTORED' using errcode='55000';end if;
  if private.closure_source_digest_v5() is distinct from target_source
     or (select sha256 from private.closure_source_v5 where singleton) is distinct from target_source
     or (select sha256 from private.closure_erasure_source_v5 where singleton) is distinct from target_source
     or private.retention_ai_source_ready() is distinct from true
     or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from target_source then
    raise exception 'D12_REVERT_CERTIFIED_POSTCONDITION' using errcode='55000';end if;
  if exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
     or has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE')
     or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE') then
    raise exception 'D12_REVERT_FINAL_AUTHORITY_OR_STATE_DRIFT' using errcode='55000';end if;
  perform pg_notify('pgrst','reload schema');
end
$d12_revert$;
